#[test]
fn bindgen_test_layout_grpc_completion_queue_functor() {
    const UNINIT: ::std::mem::MaybeUninit<grpc_completion_queue_functor> =
        ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<grpc_completion_queue_functor>(),
        24usize,
        concat!("Size of: ", stringify!(grpc_completion_queue_functor))
    );
    assert_eq!(
        ::std::mem::align_of::<grpc_completion_queue_functor>(),
        8usize,
        concat!("Alignment of ", stringify!(grpc_completion_queue_functor))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).functor_run) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(grpc_completion_queue_functor),
            "::",
            stringify!(functor_run)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).inlineable) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(grpc_completion_queue_functor),
            "::",
            stringify!(inlineable)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).internal_success) as usize - ptr as usize },
        12usize,
        concat!(
            "Offset of field: ",
            stringify!(grpc_completion_queue_functor),
            "::",
            stringify!(internal_success)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).internal_next) as usize - ptr as usize },
        16usize,
        concat!(
            "Offset of field: ",
            stringify!(grpc_completion_queue_functor),
            "::",
            stringify!(internal_next)
        )
    );
}
