#[test]
fn bindgen_test_layout_gpr_log_func_args() {
    const UNINIT: ::std::mem::MaybeUninit<gpr_log_func_args> = ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<gpr_log_func_args>(),
        24usize,
        concat!("Size of: ", stringify!(gpr_log_func_args))
    );
    assert_eq!(
        ::std::mem::align_of::<gpr_log_func_args>(),
        8usize,
        concat!("Alignment of ", stringify!(gpr_log_func_args))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).file) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(gpr_log_func_args),
            "::",
            stringify!(file)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).line) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(gpr_log_func_args),
            "::",
            stringify!(line)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).severity) as usize - ptr as usize },
        12usize,
        concat!(
            "Offset of field: ",
            stringify!(gpr_log_func_args),
            "::",
            stringify!(severity)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).message) as usize - ptr as usize },
        16usize,
        concat!(
            "Offset of field: ",
            stringify!(gpr_log_func_args),
            "::",
            stringify!(message)
        )
    );
}
